import{_ as i,l as s,o as a,c,v as t,p as d,x as r,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"接收路径","description":"","frontmatter":{"title":"接收路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rx-path.md","filePath":"cs/rx-path.md","lastUpdated":1789023840000}'),_={name:"cs/rx-path.md"};function h(f,e,u,P,m,T){const o=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="接收路径" tabindex="-1">接收路径 <a class="header-anchor" href="#接收路径" aria-label="Permalink to &quot;接收路径&quot;">​</a></h1><div class="epigraph"><p>一帧从 NAPI 进入协议钩子：以太网 → IP → L4，再由套接字查找把 sk_buff 挂进接收队列，唤醒读者。</p><footer>—— 据 Benvenuti, <em>ULNI</em>；Linux 对 netif_receive_skb 之后路径的文档</footer></div><p><a href="/cs/gro-gso">GRO</a> 把 skb 交给 <code>netif_receive_skb</code>。缺口是 <strong>整条 RX</strong>：ptype 分发、iptables 前半、路由、TCP 输入、直到 <code>sk_data_ready</code>。本课串路径，不把 TCP 拥塞算法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>驱动不知哪个进程要这包。内核：根据以太网类型找 <code>packet_type</code>，IP 查 fib，再 <code>tcp_v4_rcv</code> 用四元组找 <code>sock</code>。无套接字则 drop 或 ICMP。缺口：early demux、RPS/RFS 把包steer到 CPU；<a href="/cs/netfilter-conntrack">netfilter</a> 钩子插在 PREROUTING/INPUT；用户未 <code>read</code> 则队列有上限，超则丢——背压后课。本课不把 XDP 的先发制人展开，只承认它可在 NAPI 更早 drop/redirect。</p><p><span class="marginnote">busy poll 时用户线程可能自己把包从队列取走。抓包 AF_PACKET 在 ptype 上再挂一个处理者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>netif_receive_skb</code> → ingress qdisc（可选）→ <code>ip_rcv</code> → netfilter → <code>ip_local_deliver</code> → L4。TCP：状态机、缓冲、ACK。对照存储 RX：没有「文件偏移」，只有端口与地址。对照 <a href="/cs/device-nodes">设备节点</a>：<code>/dev/net/tun</code> 会在这条路径中途插入。</p>',8)),(a(),d(p,null,{default:r(()=>[n(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAPI%5B%22NAPI%20poll%22%5D%20--%3E%20GRO%5B%22GRO%22%5D%0A%20%20GRO%20--%3E%20ETH%5B%22eth_type_trans%22%5D%0A%20%20ETH%20--%3E%20IP%5B%22ip_rcv%22%5D%0A%20%20IP%20--%3E%20L4%5B%22tcp%2Fudp_rcv%22%5D%0A%20%20L4%20--%3E%20Q%5B%22sk%20%E6%8E%A5%E6%94%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20WAKE%5B%22%E5%94%A4%E9%86%92%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RX 路径是「把 DMA 来的字节变成进程可读缓冲」的编译结果：每层剥头，最后是 socket buffer。性能问题几乎都是：几次缓存未命中、几次锁、是否跨 NUMA。不要写成七层 OSI 教材重开——对象是 Linux 函数链。</p><p>与 <a href="/cs/nfs-semantics">NFS</a>：NFS 只是这路径上的一种 L4 负载。</p><p>实现上：early demux 用缓存的 sock 跳过一次查找。socket filter 与 tc ingress 可在协议层前丢包。无套接字的 TCP 段走 RST 或静默丢，取决于状态。 读法上只引用<a href="/cs/gro-gso">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>接收路径</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IPv6 扩展头的全部处理。不保证转发路径（不是本机交付）的每一跳设备。下一课对侧：从 <code>sendmsg</code> 到网卡的 TX 与 qdisc。</p><p>版本字段会变，课序钉的是机制对象「接收路径」，不是某一主线内核的结构体名。 后课默认：包经协议栈进入 sk 队列。发送如何排队整形，下一课 TX/qdisc。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RX：NAPI → 协议分发 → 套接字队列 → 唤醒。</li><li>netfilter 与 RPS 插在这条链上。</li><li>发送路径与 qdisc 是下一课。</li><li>出处：Benvenuti <em>ULNI</em>；Linux net/core；Stevens。</li></ul>',11))])}const E=i(_,[["render",h]]);export{k as __pageData,E as default};
